SELECT 'riga-castle', 'Rīga Castle', 'Riverside castle of the Livonian Order, today the residence of the President.', 'LV', r.id, 'Rīga', 'castles',
       ST_SetSRID(ST_MakePoint(24.099722, 56.950833), 4326)::geography, 150, ARRAY['https://vps-1a18ee51.vps.ovh.net/uploads/places/riga-castle.jpg'], 'Diego Delso · CC BY-SA 3.0 · Wikimedia Commons',
       'casual'::difficulty, 'Grass and gravel paths', 60, true, true, true, 'published', '{"lv":{"name":"Rīgas pils","description":"Livonijas ordeņa pils Daugavas krastā, tagad Valsts prezidenta rezidence."},"ru":{"name":"Рижский замок","description":"Замок Ливонского ордена на берегу Даугавы, ныне резиденция президента."}}'::jsonb
FROM regions r WHERE r.country = 'LV' AND r.slug = 'riga'
ON CONFLICT (slug) DO NOTHING;
INSERT INTO challenges (slug, title, description, type, category_id, place_id, country, region_id, difficulty, xp_reward, verification, status, i18n)
