VALUES ('summer-2027', 'Summer by the Sea', 'Latvia''s 500 km of coast: beaches, lighthouses and the cape where two seas meet.', '', 'seasonal', 'LV', 700, '2027-06-28 00:00 Europe/Riga'::timestamptz, '2027-09-01 00:00 Europe/Riga'::timestamptz, 'published', 10,
